#include "core.h"
#include <fstream>
#include <sstream>
#include <chrono>
#include <algorithm>
#include <psapi.h>
namespace xm {
static void Write(const fs::path& p,const std::string& value){fs::create_directories(p.parent_path());std::ofstream out(p,std::ios::binary);out.write(value.data(),value.size());if(!out)throw Failure(L"Test file write failed.");}
static std::string Read(const fs::path& p){std::ifstream in(p,std::ios::binary);return {std::istreambuf_iterator<char>(in),std::istreambuf_iterator<char>()};}
static void Require(bool value,const wchar_t* message){if(!value)throw Failure(message);}
static void Compare(const fs::path& a,const fs::path& b){Require(fs::exists(b),L"Missing extraction result");for(const auto& e:fs::recursive_directory_iterator(a)){auto dest=b/e.path().lexically_relative(a);Require(fs::exists(dest),L"Missing file or empty directory");if(e.is_regular_file())Require(Read(e.path())==Read(dest),L"File content mismatch");}}
static bool Clean(const fs::path& p){for(const auto& e:fs::recursive_directory_iterator(p))if(e.path().filename().wstring().rfind(L".xiaoma-work-",0)==0)return false;return true;}
int SelfTest(const fs::path& binary,const fs::path& root){std::ostringstream report;int passed=0,failed=0;fs::create_directories(root);Engine engine(binary);std::atomic_bool stop{false};auto begin=std::chrono::steady_clock::now();auto sample=root/L"\u6837\u672c \u4e2d\u6587 \u7a7a\u683c";auto output=root/L"Output";fs::create_directories(output);Write(sample/L"\u4e2d\u6587\u6587\u4ef6.txt",ToUtf8(L"\u5c0f\u9a6c\u538b\u7f29\u6d4b\u8bd5\uff1a\u4e2d\u6587\u8def\u5f84\u3001\u7a7a\u683c\u3001UTF-8\u3002\n"));Write(sample/L"\u7a7a\u6587\u4ef6.txt","");Write(sample/L"\u5d4c\u5957"/L"nested.txt",std::string(100000,'a'));fs::create_directories(sample/L"\u7a7a\u76ee\u5f55");
 std::string random(5*1024*1024,0);unsigned state=123456;for(auto& c:random){state^=state<<13;state^=state>>17;state^=state<<5;c=(char)state;}Write(sample/L"\u968f\u673a\u6570\u636e.bin",random);
 auto test=[&](const wchar_t* label,const std::function<void()>& action){stop=false;auto t=std::chrono::steady_clock::now();try{action();passed++;report<<"PASS ";}catch(const Failure& e){failed++;report<<"FAIL "<<ToUtf8(e.message)<<" | ";}catch(const std::exception& e){failed++;report<<"FAIL "<<e.what()<<" | ";}catch(...){failed++;report<<"FAIL unexpected | ";}report<<ToUtf8(label)<<" | "<<std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-t).count()<<" ms\n";};
 std::vector<fs::path> selected{sample};
 for(const auto& format:{L"zip",L"7z",L"tar"})test((std::wstring(format)+L" Compress/Directory listing/Verify/Extract/Byte-by-byte comparison").c_str(),[&](){Options o;o.format=format;auto pack=root/(std::wstring(L"Normal.")+format);auto artifacts=engine.Compress(selected,pack,o,stop);Require(artifacts.size()==1,L"Mismatched result count");auto list=engine.List(pack,L"",stop);Require(list.entries.size()>=6,L"Missing directory entries");engine.Test(pack,L"",stop);auto result=engine.Extract(pack,output,L"",stop);Compare(sample,result/sample.filename());});
 for(const auto& format:{L"zip",L"7z"})test((std::wstring(format)+L" AES Password/Incorrect password rejected/Extract").c_str(),[&](){Options o;o.format=format;o.password=o.format==L"zip"?L"sample-123!":L"\u4e2d\u6587\u5bc6\u7801 sample-123!";auto pack=root/(std::wstring(L"Encrypted.")+format);engine.Compress(selected,pack,o,stop);bool denied=false;try{engine.Extract(pack,output,L"wrong-password",stop);}catch(const Failure&){denied=true;}Require(denied,L"Incorrect password not rejected");auto result=engine.Extract(pack,output,o.password,stop);Compare(sample,result/sample.filename());Require(Clean(output),L"Failed password leaves temporary directory");});
 test(L"ZIP Chinese password provides clear prompt/Does not leave archive",[&](){Options o;o.password=L"\u4e2d\u6587\u5bc6\u7801";bool denied=false;try{engine.Compress(selected,root/L"\u4e2d\u6587\u5bc6\u7801.zip",o,stop);}catch(const Failure& e){denied=e.message.find(L"7z")!=std::wstring::npos;}Require(denied,L"ZIP Chinese password prompt is unclear");Require(!fs::exists(root/L"\u4e2d\u6587\u5bc6\u7801.zip"),L"Leaves Chinese password ZIP Incomplete file");});
 test(L"7z Split volumes/Automatic volume continuation during extraction",[&](){Options o;o.format=L"7z";o.volumeMB=1;auto parts=engine.Compress(selected,root/L"Split volumes.7z",o,stop);Require(parts.size()>=5,L"Mismatched volume count");auto result=engine.Extract(parts.front(),output,L"",stop);Compare(sample,result/sample.filename());});
 test(L"Duplicate name auto-avoidance/Preserve original result",[&](){auto first=engine.Extract(root/L"Normal.zip",output,L"",stop);auto second=engine.Extract(root/L"Normal.zip",output,L"",stop);Require(first!=second,L"Same-named result overwrites");Compare(sample,first/sample.filename());Compare(sample,second/sample.filename());});
 test(L"Rejects compression target inside source directory",[&](){bool denied=false;try{engine.Compress(selected,sample/L"inside.zip",Options{},stop);}catch(const Failure&){denied=true;}Require(denied,L"Recursive output not rejected");});
 test(L"Existing archive not overwritten",[&](){auto before=Read(root/L"Normal.zip");bool denied=false;try{engine.Compress(selected,root/L"Normal.zip",Options{},stop);}catch(const Failure&){denied=true;}Require(denied,L"Not overwriting denied");Require(before==Read(root/L"Normal.zip"),L"An archive has already been modified");});
 test(L"Canceling archive compression in background/Temporary directory cleanup",[&](){Options o;o.format=L"7z";o.level=7;bool cancelled=false;auto reporter=[&](const Progress& p){if(p.percent>=0)stop=true;};try{engine.Compress(selected,root/L"Cancel.7z",o,stop,reporter);}catch(const Cancelled&){cancelled=true;}Require(cancelled,L"Canceling ineffective operation");Require(!fs::exists(root/L"Cancel.7z"),L"Leave half-finished product");Require(Clean(root),L"Cancel leftover temporary directory");});
 test(L"Canceling decompression in background/Temporary directory cleanup",[&](){bool cancelled=false;try{engine.Extract(root/L"Normal.zip",output,L"",stop,[&](const Progress& p){if(p.percent>=0)stop=true;});}catch(const Cancelled&){cancelled=true;}Require(cancelled,L"Canceling ineffective operation");Require(Clean(root),L"Decompression cancels leftover temporary directory");});
 test(L"Path traversal/Absolute path/ADS/Device name validation",[&](){for(const auto& name:{L"../escape.txt",L"a/../../escape.txt",L"C:\\escape.txt",L"\\\\server\\share",L"file:stream",L"CON.txt",L"dir/NUL",L"name. ",L"a\\..\\out.txt"}){bool denied=false;try{ValidateEntry(name);}catch(const Failure&){denied=true;}Require(denied,L"Dangerous path not denied");}ValidateEntry(L"./Safe path/Chinese.txt");});
 test(L"Damaged archive rejected/No output left",[&](){Write(root/L"Damaged.zip","invalid zip data");bool denied=false;try{engine.Extract(root/L"Damaged.zip",output,L"",stop);}catch(const Failure&){denied=true;}Require(denied,L"Damaged archive not rejected");Require(!fs::exists(output/L"Damaged"),L"Damaged archive leaves output");});
 const auto fixtures=root.parent_path()/L"fixtures";
 for(const auto& name:{L"rar5.rar",L"\u5bc6\u7801.rar",L"tar.gz",L"sample.cab",L"source.txt.gz",L"source.txt.bz2",L"source.txt.xz",L"source.txt.zst"})test((std::wstring(name)+L" Independent kernel decompression").c_str(),[&](){Require(fs::exists(fixtures/name),L"Test sample missing");auto result=engine.Extract(fixtures/name,output,std::wstring(name)==L"\u5bc6\u7801.rar"?L"sample-123":L"",stop);Require(Read(result/L"source.txt")==Read(fixtures/L"source.txt"),L"External format content mismatch");});
 test(L"RAR Multi-part decompression",[&](){auto result=engine.Extract(fixtures/L"vol.part1.rar",output,L"",stop);Require(Read(result/L"random.bin")==Read(fixtures/L"random.bin"),L"RAR Multi-part content mismatch");});
 for(const auto& name:{L"traversal.zip",L"absolute.zip",L"ads.zip",L"device.zip",L"symlink.zip",L"tar-link.tar",L"tar-link.tgz"})test((std::wstring(name)+L" Actual malicious archive rejected").c_str(),[&](){bool denied=false;try{engine.Extract(fixtures/name,output,L"",stop);}catch(const Failure&){denied=true;}Require(denied,L"Dangerous archive not rejected");Require(Clean(root),L"Leftover temporary directory after rejection");});
 test(L"20000 Directory entry read (virtual list)",[&](){auto list=engine.List(fixtures/L"many.zip",L"",stop);Require(list.entries.size()==20000,L"Missing large directory entry");});
 test(L"Balanced/Smaller 7z and ZIP",[&](){for(auto format:{L"zip",L"7z"})for(int level:{5,7}){Options o;o.format=format;o.level=level;auto pack=root/(std::wstring(format)+std::to_wstring(level)+L"."+format);engine.Compress({sample/L"\u5d4c\u5957"},pack,o,stop);auto result=engine.Extract(pack,output,L"",stop);Compare(sample/L"\u5d4c\u5957",result/L"\u5d4c\u5957");}});

 test(L"Streaming check 20000 Directory entry: not saving entry",[&](){auto a=engine.Inspect(fixtures/L"many.zip",L"",stop);Require(a.entries.empty()&&a.count==20000&&a.total==20000,L"Streaming check statistics mismatch");});
 test(L"Extract only selected files",[&](){auto member=sample.filename().wstring()+L"\\\u4e2d\u6587\u6587\u4ef6.txt";auto result=engine.Extract(root/L"Normal.zip",output,L"",stop,{}, {member});Require(Read(result/sample.filename()/L"\u4e2d\u6587\u6587\u4ef6.txt")==Read(sample/L"\u4e2d\u6587\u6587\u4ef6.txt"),L"Incorrect file content selected");Require(!fs::exists(result/sample.filename()/L"\u968f\u673a\u6570\u636e.bin"),L"Extracted unselected file");});
 test(L"Recursive extraction of selected directory and empty directories",[&](){auto base=sample.filename().wstring();auto result=engine.Extract(root/L"Normal.7z",output,L"",stop,{}, {base+L"\\\u5d4c\u5957",base+L"\\\u7a7a\u76ee\u5f55"});Compare(sample/L"\u5d4c\u5957",result/sample.filename()/L"\u5d4c\u5957");Require(fs::is_directory(result/sample.filename()/L"\u7a7a\u76ee\u5f55"),L"Empty directory not extracted");Require(!fs::exists(result/sample.filename()/L"\u4e2d\u6587\u6587\u4ef6.txt"),L"Extracted irrelevant files");});
 test(L"Refused to extract non-existent selected item",[&](){bool denied=false;try{engine.Extract(root/L"Normal.zip",output,L"",stop,{}, {L"missing.txt"});}catch(const Failure&){denied=true;}Require(denied,L"Non-existent item not refused");Require(Clean(root),L"Left temporary directory");});
 test(L"Inside package UTF-8 Text read-only preview and temporary cleanup",[&](){auto text=engine.ReadText(root/L"Normal.zip",sample.filename().wstring()+L"\\\u4e2d\u6587\u6587\u4ef6.txt",L"",stop);Require(text.find(L"\u5c0f\u9a6c\u538b\u7f29\u6d4b\u8bd5")!=std::wstring::npos&&text.find(L"\r\n")!=std::wstring::npos,L"UTF-8 Preview error");});
 test(L"UTF-16LE Text preview and 2 MB Limit",[&](){auto folder=root/L"Preview source";Write(folder/L"utf16.txt",std::string("\xff\xfe\x2d\x4e\x87\x65",6));Write(folder/L"large.txt",std::string(3*1024*1024,'x'));auto pack=root/L"Preview.zip";engine.Compress({folder},pack,Options{},stop);Require(engine.ReadText(pack,L"Preview source/utf16.txt",L"",stop)==L"\u4e2d\u6587",L"UTF-16 Preview error");bool denied=false;try{engine.ReadText(pack,L"Preview source/large.txt",L"",stop);}catch(const Failure&){denied=true;}Require(denied,L"Exceeded preview limit without refusal");});
 test(L"Binary content will not be executed or treated as text preview",[&](){bool denied=false;try{engine.ReadText(root/L"Normal.zip",sample.filename().wstring()+L"\\\u968f\u673a\u6570\u636e.bin",L"",stop);}catch(const Failure&){denied=true;}Require(denied,L"Binary preview not refused");});
 test(L"RAR Second volume automatically locates first volume",[&](){Require(FirstVolume(fixtures/L"vol.part2.rar")==fs::absolute(fixtures/L"vol.part1.rar"),L"RAR First volume location failed");auto result=engine.Extract(fixtures/L"vol.part2.rar",output,L"",stop);Require(Read(result/L"random.bin")==Read(fixtures/L"random.bin"),L"Decompression error on non-first volume");});
 test(L"7z Second volume automatically locates with missing first volume rejected",[&](){auto result=engine.Extract(root/L"Split volumes.7z.002",output,L"",stop);Compare(sample,result/sample.filename());Write(root/L"Missing first volume.7z.002","x");bool denied=false;try{engine.Extract(root/L"Missing first volume.7z.002",output,L"",stop);}catch(const Failure& e){denied=e.message.find(L"first volume")!=std::wstring::npos;}Require(denied,L"Missing first volume prompt failed");});
 test(L"ZIP/7z Only packaging and byte-by-byte comparison",[&](){for(auto fmt:{L"zip",L"7z"}){Options o;o.format=fmt;o.level=0;auto pack=root/(std::wstring(L"Store only.")+fmt);engine.Compress({sample},pack,o,stop);auto result=engine.Extract(pack,output,L"",stop);Compare(sample,result/sample.filename());}});
 test(L"Compressed media intelligently skipped compression",[&](){auto media=root/L"Video.mp4";Write(media,random);auto pack=root/L"Intelligent.zip";engine.Compress({media},pack,Options{},stop);Require(fs::file_size(pack)<random.size()+1024,L"Intelligent packaging with abnormal overhead only");auto result=engine.Extract(pack,output,L"",stop);Require(Read(result/L"Video.mp4")==random,L"Inconsistency in intelligent packaging content");});
 for(auto format:{L"zip",L"7z"})test((std::wstring(format)+L" Add/Cover/Delete/Original Package Backup Comparison").c_str(),[&](){auto pack=root/(std::wstring(L"Modify.")+format);fs::copy_file(root/(std::wstring(L"Normal.")+format),pack);auto before=Read(pack);auto addition=root/L"\u65b0\u589e \u4e2d\u6587.txt";Write(addition,"version one");auto backup=engine.Modify(pack,{addition},{},L"",stop);Require(Read(backup)==before,L"Original Package Backup Content Inconsistent");auto list=engine.List(pack,L"",stop);Require(std::any_of(list.entries.begin(),list.entries.end(),[](const Entry& e){return e.name==L"\u65b0\u589e \u4e2d\u6587.txt";}),L"New Content Does Not Exist");Write(addition,"version two");engine.Modify(pack,{addition},{},L"",stop);auto result=engine.Extract(pack,output,L"",stop,{}, {L"\u65b0\u589e \u4e2d\u6587.txt"});Require(Read(result/L"\u65b0\u589e \u4e2d\u6587.txt")=="version two",L"Cover Content Inconsistent");engine.Modify(pack,{}, {L"\u65b0\u589e \u4e2d\u6587.txt",sample.filename().wstring()+L"\\\u5d4c\u5957"},L"",stop);list=engine.List(pack,L"",stop);Require(std::none_of(list.entries.begin(),list.entries.end(),[&](const Entry& e){return e.name==L"\u65b0\u589e \u4e2d\u6587.txt"||e.name.find(L"\u5d4c\u5957")!=std::wstring::npos;}),L"Deleted Entry Still Exists");Require(Clean(root),L"Modify Leaves Temporary Directory");});
 test(L"Encrypted 7z Directory Encryption Retained After Modification",[&](){auto pack=root/L"Modify Encryption.7z";fs::copy_file(root/L"Encrypted.7z",pack);auto source=root/L"Encrypt New Content.txt";Write(source,"private test");engine.Modify(pack,{source},{},L"\u4e2d\u6587\u5bc6\u7801 sample-123!",stop);bool denied=false;try{engine.List(pack,L"",stop);}catch(const Failure& e){denied=e.password;}Require(denied,L"Directory Encryption Lost After Update");auto result=engine.Extract(pack,output,L"\u4e2d\u6587\u5bc6\u7801 sample-123!",stop,{}, {L"Encrypt New Content.txt"});Require(Read(result/L"Encrypt New Content.txt")=="private test",L"Encryption Update Content Inconsistent");});
 test(L"Update Failed/Cancel Maintains Original Package Byte-for-Byte",[&](){auto pack=root/L"Modify Failed.zip";fs::copy_file(root/L"Normal.zip",pack);auto before=Read(pack);bool denied=false;try{engine.Modify(pack,{root/L"not-found.txt"},{},L"",stop);}catch(const Failure&){denied=true;}Require(denied&&Read(pack)==before,L"Update Failed and Altered Original Package");stop=true;bool cancelled=false;try{engine.Modify(pack,{}, {sample.filename().wstring()+L"\\\u4e2d\u6587\u6587\u4ef6.txt"},L"",stop);}catch(const Cancelled&){cancelled=true;}stop=false;Require(cancelled&&Read(pack)==before,L"Update Cancelled and Altered Original Package");Require(Clean(root),L"Update Failed and Left Temporary Data");});
 test(L"RAR Rejects Modify and Split Modify",[&](){for(auto p:{fixtures/L"rar5.rar",root/L"Split volumes.7z.001"}){auto before=Read(p);bool denied=false;try{engine.Modify(p,{}, {L"source.txt"},L"",stop);}catch(const Failure&){denied=true;}Require(denied&&Read(p)==before,L"Unsupported Package Was Modified");}});
 test(L"RAR Convert ZIP/ZIP Convert 7z Original Retained",[&](){auto before=Read(fixtures/L"rar5.rar");auto parts=engine.Convert(fixtures/L"rar5.rar",root/L"Convert.zip",Options{},L"",stop);auto result=engine.Extract(parts.front(),output,L"",stop);Require(Read(result/L"source.txt")==Read(fixtures/L"source.txt"),L"RAR Convert ZIP Content Error");Require(Read(fixtures/L"rar5.rar")==before,L"Conversion Alters Original");Options o;o.format=L"7z";parts=engine.Convert(root/L"Normal.zip",root/L"Convert.7z",o,L"",stop);result=engine.Extract(parts.front(),output,L"",stop);Compare(sample,result/sample.filename());});
 PROCESS_MEMORY_COUNTERS pm{};pm.cb=sizeof(pm);GetProcessMemoryInfo(GetCurrentProcess(),&pm,sizeof(pm));report<<"\nTOTAL "<<passed<<" passed, "<<failed<<" failed\nDuration seconds: "<<std::chrono::duration<double>(std::chrono::steady_clock::now()-begin).count()<<"\nTest runner peak working set bytes: "<<pm.PeakWorkingSetSize<<"\nEngine child peak working set bytes: "<<EnginePeakMemory()<<"\n";Write(root/L"Test Report.txt",report.str());return failed?1:0;
}
}
